package com.agychat.app.ui.common

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.ColorFilter
import android.graphics.Paint
import android.graphics.PixelFormat
import android.graphics.drawable.Drawable
import android.util.Base64
import java.io.ByteArrayOutputStream
import java.util.zip.Inflater

/**
 * EXACT CODE-ONLY reconstruction of the Next AI / Google Antigravity Neon Glass Logo.
 *
 * No PNG/JPG/WebP/SVG/vector asset is required at runtime.
 * The source image's raw RGBA pixels are losslessly zlib-compressed
 * and embedded in this Kotlin source. The Bitmap is reconstructed
 * pixel-for-pixel from those bytes and cached statically for 120 FPS performance.
 *
 * Source dimensions: 1254 x 1254
 * Source format: RGBA_8888
 * Compression: zlib (lossless)
 */
class NeonGlassLogoExactDrawable : Drawable() {
    private val paint = Paint(Paint.ANTI_ALIAS_FLAG or Paint.FILTER_BITMAP_FLAG).apply {
        isDither = false
        isFilterBitmap = true
    }

    private val bitmap: Bitmap get() = getExactBitmap()

    override fun draw(canvas: Canvas) {
        canvas.drawBitmap(bitmap, null, bounds, paint)
    }

    override fun setAlpha(alpha: Int) {
        paint.alpha = alpha
    }

    override fun setColorFilter(colorFilter: ColorFilter?) {
        paint.colorFilter = colorFilter
    }

    @Suppress("DEPRECATION")
    override fun getOpacity(): Int = PixelFormat.TRANSLUCENT

    override fun getIntrinsicWidth(): Int = SOURCE_WIDTH
    override fun getIntrinsicHeight(): Int = SOURCE_HEIGHT

    companion object {
        const val SOURCE_WIDTH = 1254
        const val SOURCE_HEIGHT = 1254
        private const val SOURCE_RAW_BYTES = 6290064

        @Volatile
        private var cachedBitmap: Bitmap? = null

        /**
         * Returns the reconstructed 1254x1254 pixel-perfect Bitmap.
         * Decompresses lazily only once across the entire application lifecycle.
         */
        fun getExactBitmap(): Bitmap {
            return cachedBitmap ?: synchronized(this) {
                cachedBitmap ?: buildExactBitmap().also { cachedBitmap = it }
            }
        }

        private fun buildExactBitmap(): Bitmap {
            val compressed = Base64.decode(PNG_DATA_ZLIB_BASE64, Base64.DEFAULT)
            val rgba = inflateExact(compressed, SOURCE_RAW_BYTES)
            val pixels = IntArray(SOURCE_WIDTH * SOURCE_HEIGHT)

            var p = 0
            for (i in pixels.indices) {
                val r = rgba[p++].toInt() and 0xFF
                val g = rgba[p++].toInt() and 0xFF
                val b = rgba[p++].toInt() and 0xFF
                val a = rgba[p++].toInt() and 0xFF
                pixels[i] = (a shl 24) or (r shl 16) or (g shl 8) or b
            }

            return Bitmap.createBitmap(SOURCE_WIDTH, SOURCE_HEIGHT, Bitmap.Config.ARGB_8888).also {
                it.setPixels(pixels, 0, SOURCE_WIDTH, 0, 0, SOURCE_WIDTH, SOURCE_HEIGHT)
            }
        }

        private fun inflateExact(data: ByteArray, expectedSize: Int): ByteArray {
            val inflater = Inflater()
            inflater.setInput(data)
            val output = ByteArrayOutputStream(expectedSize)
            val buffer = ByteArray(64 * 1024)

            try {
                while (!inflater.finished()) {
                    val count = inflater.inflate(buffer)
                    if (count == 0 && inflater.needsInput()) break
                    if (count == 0 && inflater.needsDictionary()) {
                        error("Unexpected zlib dictionary requirement")
                    }
                    output.write(buffer, 0, count)
                }
            } finally {
                inflater.end()
            }

            return output.toByteArray().also {
                check(it.size == expectedSize) {
                    "Logo data is corrupted: expected $expectedSize bytes, got ${it.size}"
                }
            }
        }

